from .config import loggers as ute_ue_logging
from .lteue import LteUe
from .utils import instance_id
from .config.abstract_core_logger_wrapper import create_logger


class LteUeGroup(LteUe):
    """LTE Ue group general object"""

    def __init__(self, ues, name=None, configuration=None):
        """
        Definition of Abstract UE API
        :param configuration: anything required to instantiate specific UE group
        :return: None
        """
        self._name = name or instance_id(self)
        self._configuration = configuration if configuration else {}
        self.ues = ues
        logger_name = f'ute_ue.ue_group.{self.name}'
        self.logger = create_logger(logger_name, self.logger_logname)

    def __str__(self):
        return f"{self.__class__.__name__}({self._ue_quantity_str()} '{self.name}')"

    def __repr__(self):
        return f"{self.__class__.__name__}({self._ue_quantity_str()} '{self.name}', at {hex(id(self))})"

    @property
    def name(self):
        """Get name of UE-group"""
        return self._name

    @name.setter
    def name(self, value):
        """
        Set name of UE-group

        Modify logger after name change.
        """
        if value != self._name:
            self.logger.debug(f'changing UE-group name: {self._name} --> {value}')
            self._name = value
            try:
                ute_ue_logging.exchange_filename(logger=self.logger, new_filename=self.logger_logname)
            except Exception as err:  # pylint: disable=broad-except
                # logging related actions should not break UE-group
                self.logger.warning(f'failed changing UE-group logname to {self.logger_logname}, {err!r}')

    @property
    def logger_logname(self):
        """Get filename of log for UE-group logger"""
        return f'ue_group.{self.name}.log'

    def _ue_quantity_str(self):
        return f"{len(self.ues)} UEs"

    def attach(self, success_ratio, failure_ratio, timeout=-1, **kwargs):
        """
        Perform attach on UEs in group.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        :raises: :py:class:`ute_ue.exceptions.UeProcedureTimeout`: If attach exceeded desired time
        """
        raise NotImplementedError

    # all other methods are same as methods of LteUe
    # just meaning differs little bit, like:
    # attach() means perform attach on each UE of group, etc.
